// Display name in one place. index.html, the PWA manifest (both generated by vite.config.ts), the header, the
// page title and the backup file name all read from here. Internal identifiers (IndexedDB 'nhip', backup
// app 'nhip', localStorage keys, repository and Pages path) do not depend on the display name.
export const APP_NAME = 'The Study Hub';
export const APP_SHORT_NAME = 'Study Hub';
export const APP_SUBTITLE = 'tracking-status';
export const BACKUP_PREFIX = 'study-hub-backup';
export const APP_DESCRIPTION =
  'Theo dõi topic học mỗi ngày: lộ trình đầy đủ, sprint 2 đến 4 tuần có sản phẩm cụ thể, học một chút mỗi ngày, đồng hồ buổi học và nhìn lại tuần. Dữ liệu nằm hoàn toàn trong trình duyệt.';

export function manifest(): Record<string, unknown> {
  return {
    name: APP_NAME,
    short_name: APP_SHORT_NAME,
    description: APP_DESCRIPTION,
    lang: 'vi',
    start_url: './',
    scope: './',
    display: 'standalone',
    background_color: '#f5f7fa',
    theme_color: '#f5f7fa',
    icons: [{ src: 'icon.svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any' }],
  };
}
